// Preparar contexto da execução com token e datas
const auth = $('🔐 Autenticar Dapic').first().json;
const periodo = $('📅 Definir Período').first().json;

if (!auth.access_token) {
  throw new Error('Falha na autenticação Dapic: access_token não retornado');
}

return [{
  json: {
    token: auth.access_token,
    dataHoje: periodo.dataHoje,
    data30DiasAtras: periodo.data30DiasAtras,
    data90DiasAtras: periodo.data90DiasAtras,
    dataMais30Dias: periodo.dataMais30Dias,
    dataMais7Dias: periodo.dataMais7Dias,
    baseUrl: 'https://api.dapic.app',
    iniciadoEm: new Date().toISOString()
  }
}];

// ============================================================
// COLETAR VENDAS — Pedidos B2B + PDV + Produtos Vendidos
// ============================================================
const ctx = $('💾 Preparar Contexto').first().json;
const { token, dataHoje, data30DiasAtras, baseUrl } = ctx;

async function fetchAllPages(endpoint, params = {}) {
  let allData = [];
  let pagina = 1;
  let totalPaginas = 1;

  do {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `${baseUrl}${endpoint}`,
      headers: { 'Authorization': `Bearer ${token}` },
      qs: { ...params, Pagina: pagina, RegistrosPorPagina: 200 },
      json: true
    });

    if (response.Dados && response.Dados.length > 0) {
      allData = allData.concat(response.Dados);
    }
    totalPaginas = response.TotalPaginas || 1;

    if (pagina < totalPaginas) {
      await new Promise(r => setTimeout(r, 650));
    }
    pagina++;
  } while (pagina <= totalPaginas);

  return allData;
}

// 1. Pedidos de Venda B2B (faturados)
const pedidosVenda = await fetchAllPages.call(this, '/v1/pedidosvendas', {
  DataInicial: data30DiasAtras,
  DataFinal: dataHoje,
  Status: 5,
  FiltrarPor: 0
});

await new Promise(r => setTimeout(r, 650));

// 2. Vendas PDV
const vendasPDV = await fetchAllPages.call(this, '/v1/vendas', {
  DataInicial: data30DiasAtras,
  DataFinal: dataHoje,
  Status: 5
});

await new Promise(r => setTimeout(r, 650));

// 3. Produtos Vendidos (consolidado para ranking)
const produtosVendidos = await fetchAllPages.call(this, '/v1/vendas/produtosvendidos', {
  DataInicial: data30DiasAtras,
  DataFinal: dataHoje
});

return [{ json: { pedidosVenda, vendasPDV, produtosVendidos, coletadoEm: new Date().toISOString() } }];

