// 1. Estoque atual (todos os armazenadores)
const estoqueAtual = await fetchAllPages.call(this, '/v1/estoques/todos');

// 2. Movimentações últimos 30 dias (rate limit: max 31d por request)
await new Promise(r => setTimeout(r, 2000)); // endpoint volumoso
const movimentacoes30d = await fetchAllPages.call(this, '/v1/movimentacoesestoque', {
  DataInicial: data30DiasAtras,
  DataFinal: dataHoje
