// 3. Movimentações esta semana vs semana anterior (para tendência)
const hoje = new Date();
const inicioSemanaAtual = new Date(hoje);
inicioSemanaAtual.setDate(hoje.getDate() - hoje.getDay());
const inicioSemanaAnterior = new Date(inicioSemanaAtual);
inicioSemanaAnterior.setDate(inicioSemanaAtual.getDate() - 7);

await new Promise(r => setTimeout(r, 2000));
const movimentacoesSemanaAnterior = await fetchAllPages.call(this, '/v1/movimentacoesestoque', {
