// Parcelas a pagar: período amplo (vencidos + próximos 30d)
const parcelasPagar = await fetchAllPages.call(this, '/v1/contas/parcelas', {
  DataInicial: data90DiasAtras,
  DataFinal: dataMais30Dias,
  FiltrarPor: 0
});

// Filtrar apenas Contas a Pagar (Tipo = Pagar)
const contasPagar = parcelasPagar.filter(p => 
  (String(p.Tipo || p.tipo || p.TipoLancamento || p.Natureza || '').toLowerCase()).includes('pagar')
);

return [{ json: { contasPagar, coletadoEm: new Date().toISOString() } }];

// ============================================================
// COLETAR CONTAS A RECEBER
// ============================================================
const ctx = $('💾 Preparar Contexto').first().json;
const { token, dataHoje, data90DiasAtras, dataMais30Dias, baseUrl } = ctx;

async function fetchAllPages(endpoint, params = {}) {
  let allData = [];
  let pagina = 1;
  let totalPaginas = 1;

  do {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `${baseUrl}${endpoint}`,
      headers: { 'Authorization': `Bearer ${token}` },
      qs: { ...params, Pagina: pagina, RegistrosPorPagina: 200 },
      json: true
    });

    if (response.Dados && response.Dados.length > 0) {
      allData = allData.concat(response.Dados);
    }
    totalPaginas = response.TotalPaginas || 1;

    if (pagina < totalPaginas) {
      await new Promise(r => setTimeout(r, 650));
    }
    pagina++;
  } while (pagina <= totalPaginas);

  return allData;
}

// Parcelas a receber
const todasParcelas = await fetchAllPages.call(this, '/v1/contas/parcelas', {
  DataInicial: data90DiasAtras,
  DataFinal: dataMais30Dias,
  FiltrarPor: 0
});

// Filtrar apenas Contas a Receber
const contasReceber = todasParcelas.filter(p =>
  (String(p.Tipo || p.tipo || p.TipoLancamento || p.Natureza || '').toLowerCase()).includes('receber')
);

return [{ json: { contasReceber, coletadoEm: new Date().toISOString() } }];

// ============================================================
// TRANSFORMAR VENDAS — Calcular KPIs
// ============================================================
const { pedidosVenda, vendasPDV, produtosVendidos } = $('📊 Coletar Vendas').first().json;
const ctx = $('💾 Preparar Contexto').first().json;

// Período anterior (mesmo número de dias imediatamente antes)
const hoje = new Date(ctx.dataHoje);
const inicio = new Date(ctx.data30DiasAtras);
const diasPeriodo = Math.floor((hoje - inicio) / (1000*60*60*24));

// Helper: agrupar por data
function agruparPorData(items, campoData, campoValor) {
  const mapa = {};
  for (const item of items) {
    const data = (item[campoData] || '').split('T')[0];
    if (!mapa[data]) mapa[data] = { data, receita: 0, volume: 0 };
    mapa[data].receita += Number(item[campoValor] || 0);
    mapa[data].volume += 1;
  }
  return Object.values(mapa).sort((a, b) => a.data.localeCompare(b.data));
}

// Receita total B2B
const receitaB2B = pedidosVenda.reduce((s, p) => s + Number(p.ValorLiquido || 0), 0);
const volumeB2B = pedidosVenda.length;

// Receita total PDV
const receitaPDV = vendasPDV.reduce((s, v) => s + Number(v.ValorLiquido || 0), 0);
const volumePDV = vendasPDV.length;

const receitaTotal = receitaB2B + receitaPDV;
const volumeTotal = volumeB2B + volumePDV;
const ticketMedio = volumeTotal > 0 ? receitaTotal / volumeTotal : 0;

// Evolução diária (combinando B2B + PDV)
const evolucaoB2B = agruparPorData(pedidosVenda, 'DataEmissao', 'ValorLiquido');
const evolucaoPDV = agruparPorData(vendasPDV, 'DataEmissao', 'ValorLiquido');

// Mesclar evoluções
const mapaEvolucao = {};
for (const d of [...evolucaoB2B, ...evolucaoPDV]) {
  if (!mapaEvolucao[d.data]) mapaEvolucao[d.data] = { data: d.data, receita: 0, volume: 0 };
  mapaEvolucao[d.data].receita += d.receita;
  mapaEvolucao[d.data].volume += d.volume;
}
const evolucaoDiaria = Object.values(mapaEvolucao).sort((a, b) => a.data.localeCompare(b.data));

// Top 10 produtos por receita
const produtosOrdenados = [...produtosVendidos]
  .sort((a, b) => Number(b.ValorTotal || b.ValorLiquido || 0) - Number(a.ValorTotal || a.ValorLiquido || 0))
  .slice(0, 10)
  .map(p => ({
    produto: p.Produto || p.Nome || p.Descricao || 'N/A',
    receita: Number(p.ValorTotal || p.ValorLiquido || 0),
    quantidade: Number(p.Quantidade || 0)
  }));

// Top 10 clientes por receita (de pedidos B2B)
const mapaClientes = {};
for (const p of pedidosVenda) {
  const cliente = p.Cliente || 'N/A';
  if (!mapaClientes[cliente]) mapaClientes[cliente] = { cliente, receita: 0, volume: 0 };
  mapaClientes[cliente].receita += Number(p.ValorLiquido || 0);
  mapaClientes[cliente].volume += 1;
}
const topClientes = Object.values(mapaClientes)
  .sort((a, b) => b.receita - a.receita)
  .slice(0, 10);

// Representantes (campo Representante nos pedidos, se disponível)
const mapaRepresentantes = {};
for (const p of pedidosVenda) {
  const rep = p.Representante || p.Vendedor || 'Direto';
  if (!mapaRepresentantes[rep]) mapaRepresentantes[rep] = { representante: rep, receita: 0, pedidos: 0 };
  mapaRepresentantes[rep].receita += Number(p.ValorLiquido || 0);
  mapaRepresentantes[rep].pedidos += 1;
}
const porRepresentante = Object.values(mapaRepresentantes)
  .sort((a, b) => b.receita - a.receita)
  .map(r => ({ ...r, ticket_medio: r.pedidos > 0 ? r.receita / r.pedidos : 0 }));

const vendas = {
  gerado_em: new Date().toISOString(),
  periodo: { inicio: ctx.data30DiasAtras, fim: ctx.dataHoje },
  summary: {
    receita_total: Math.round(receitaTotal * 100) / 100,
    volume_vendas: volumeTotal,
    ticket_medio: Math.round(ticketMedio * 100) / 100,
    variacao_mes_anterior_pct: 0, // será calculado quando tivermos período anterior
    receita_b2b: Math.round(receitaB2B * 100) / 100,
    receita_pdv: Math.round(receitaPDV * 100) / 100
  },
  evolucao_diaria: evolucaoDiaria,
  top_produtos: produtosOrdenados,
  top_clientes: topClientes,
  por_representante: porRepresentante
};

return [{ json: { modulo: 'vendas', dados: vendas } }];

// ============================================================
// TRANSFORMAR ESTOQUE — Calcular KPIs de Reposição
// ============================================================
const { estoqueAtual, movimentacoes30d, movimentacoesSemanaAnterior } = $('📦 Coletar Estoque').first().json;
const ctx = $('💾 Preparar Contexto').first().json;

const hoje = new Date(ctx.dataHoje);

// Calcular venda média diária por produto (últimos 30 dias)
const vendasPorProduto = {};
for (const mov of movimentacoes30d) {
  const produto = mov.Produto || mov.CodigoProduto || 'N/A';
  const quantidade = Math.abs(Number(mov.Quantidade || 0));
  const tipo = (mov.Tipo || mov.TipoMovimento || '').toLowerCase();

  // Apenas saídas (vendas)
  if (tipo.includes('saida') || tipo.includes('venda') || tipo.includes('saída')) {
    if (!vendasPorProduto[produto]) vendasPorProduto[produto] = 0;
    vendasPorProduto[produto] += quantidade;
  }
}

// Movimentações semana atual
const vendasSemanaAtual = {};
const inicioSemana = new Date(hoje);
inicioSemana.setDate(hoje.getDate() - hoje.getDay());

for (const mov of movimentacoes30d) {
  const dataMov = new Date((mov.DataMovimento || mov.Data || '').split('T')[0]);
  if (dataMov >= inicioSemana) {
    const produto = mov.Produto || mov.CodigoProduto || 'N/A';
    const quantidade = Math.abs(Number(mov.Quantidade || 0));
    const tipo = (mov.Tipo || mov.TipoMovimento || '').toLowerCase();
    if (tipo.includes('saida') || tipo.includes('venda') || tipo.includes('saída')) {
      if (!vendasSemanaAtual[produto]) vendasSemanaAtual[produto] = 0;
      vendasSemanaAtual[produto] += quantidade;
    }
  }
}

// Movimentações semana anterior
const vendasSemAnt = {};
for (const mov of movimentacoesSemanaAnterior) {
  const produto = mov.Produto || mov.CodigoProduto || 'N/A';
  const quantidade = Math.abs(Number(mov.Quantidade || 0));
  const tipo = (mov.Tipo || mov.TipoMovimento || '').toLowerCase();
  if (tipo.includes('saida') || tipo.includes('venda') || tipo.includes('saída')) {
    if (!vendasSemAnt[produto]) vendasSemAnt[produto] = 0;
    vendasSemAnt[produto] += quantidade;
  }
}

// Calcular indicadores por produto
let valorTotalEstoque = 0;
const saldoDia = [];
const reposicaoUrgente = [];
const tendenciaSemanal = [];

for (const item of estoqueAtual) {
  const produto = item.Produto || item.Nome || 'N/A';
  const codigo = item.CodigoProduto || item.Codigo || 'N/A';
  const estoqueQtd = Number(item.Quantidade || 0);
  const valorUnitario = Number(item.ValorUnitario || item.Preco || 0);

  valorTotalEstoque += estoqueQtd * valorUnitario;

  const vendasDia = vendasSemanaAtual[produto] ? vendasSemanaAtual[produto] / 7 : 0;
  const saldo = estoqueQtd - vendasDia;
  const statusSaldo = saldo < 0 ? 'CRITICO' : saldo < (estoqueQtd * 0.1) ? 'ALERTA' : 'OK';

  saldoDia.push({ produto, codigo, estoque_atual: estoqueQtd, vendas_hoje: Math.round(vendasDia * 10) / 10, saldo: Math.round(saldo * 10) / 10, status: statusSaldo });

  // Dias até zerar
  const vendaMediaDiaria = (vendasPorProduto[produto] || 0) / 30;
  if (vendaMediaDiaria > 0) {
    const diasAteZerar = Math.floor(estoqueQtd / vendaMediaDiaria);
    let urgencia = 'OK';
    if (diasAteZerar <= 7) urgencia = 'CRITICO';
    else if (diasAteZerar <= 15) urgencia = 'ALERTA';

    if (urgencia !== 'OK') {
      reposicaoUrgente.push({ produto, codigo, estoque_atual: estoqueQtd, venda_media_diaria: Math.round(vendaMediaDiaria * 10) / 10, dias_ate_zerar: diasAteZerar, urgencia });
    }
  }

  // Tendência semanal
  const semAtual = vendasSemanaAtual[produto] || 0;
  const semAnt = vendasSemAnt[produto] || 0;
  if (semAtual > 0 || semAnt > 0) {
    const variacaoPct = semAnt > 0 ? ((semAtual - semAnt) / semAnt) * 100 : 100;
    tendenciaSemanal.push({ produto, vendas_semana_atual: semAtual, vendas_semana_anterior: semAnt, variacao_pct: Math.round(variacaoPct * 10) / 10, tendencia: variacaoPct > 5 ? 'subindo' : variacaoPct < -5 ? 'caindo' : 'estavel' });
  }
}

// Ordenar reposição por urgência
reposicaoUrgente.sort((a, b) => a.dias_ate_zerar - b.dias_ate_zerar);

const skusCriticos = reposicaoUrgente.filter(r => r.urgencia === 'CRITICO').length;
const skusAlerta = reposicaoUrgente.filter(r => r.urgencia === 'ALERTA').length;

const estoque = {
  gerado_em: new Date().toISOString(),
  summary: {
    valor_total_estoque: Math.round(valorTotalEstoque * 100) / 100,
    skus_criticos: skusCriticos,
    skus_alerta: skusAlerta,
    giro_estoque_30d: 0
  },
  saldo_dia: saldoDia,
  reposicao_urgente: reposicaoUrgente,
  tendencia_semanal: tendenciaSemanal.sort((a, b) => Math.abs(b.variacao_pct) - Math.abs(a.variacao_pct)).slice(0, 20)
};

return [{ json: { modulo: 'estoque', dados: estoque } }];

// ============================================================
// TRANSFORMAR FINANCEIRO — CP + CR + Fluxo de Caixa
// ============================================================
const { contasPagar } = $('💸 Coletar Contas a Pagar').first().json;
const { contasReceber } = $('💰 Coletar Contas a Receber').first().json;
const ctx = $('💾 Preparar Contexto').first().json;

const hoje = new Date(ctx.dataHoje);
const daqui7Dias = new Date(ctx.dataMais7Dias);

function calcularDiasAtraso(dataVencStr) {
  const dataVenc = new Date(dataVencStr.split('T')[0]);
  return Math.floor((hoje - dataVenc) / (1000*60*60*24));
}

function getNumSemana(data) {
  const d = new Date(data);
  const startOfYear = new Date(d.getFullYear(), 0, 1);
  const weekNum = Math.ceil(((d - startOfYear) / 86400000 + startOfYear.getDay() + 1) / 7);
  return `${d.getFullYear()}-W${String(weekNum).padStart(2, '0')}`;
}

const statusPago = ['Pago', 'pago', 'Liquidado', 'Recebido', 'recebido', 'Baixado'];

// ===== CONTAS A PAGAR =====
const cpPendentes = contasPagar.filter(p => !statusPago.includes(p.Status));
const cpVencidos = cpPendentes.filter(p => new Date(p.DataVencimento) < hoje);
const cpVencendo7d = cpPendentes.filter(p => {
  const venc = new Date(p.DataVencimento);
  return venc >= hoje && venc <= daqui7Dias;
});

const totalCP = cpPendentes.reduce((s, p) => s + Number(p.Valor || 0), 0);
const totalCPVencido = cpVencidos.reduce((s, p) => s + Number(p.Valor || 0), 0);
const totalCPVencendo7d = cpVencendo7d.reduce((s, p) => s + Number(p.Valor || 0), 0);

// Fluxo semanal CP (saídas projetadas)
const fluxoCP = {};
for (const p of cpPendentes) {
  const semana = getNumSemana(p.DataVencimento.split('T')[0]);
  if (!fluxoCP[semana]) fluxoCP[semana] = 0;
  fluxoCP[semana] += Number(p.Valor || 0);
}

// ===== CONTAS A RECEBER =====
const crPendentes = contasReceber.filter(p => !statusPago.includes(p.Status));
const crInadimplentes = crPendentes.filter(p => new Date(p.DataVencimento) < hoje);
const crRecebendo7d = crPendentes.filter(p => {
  const venc = new Date(p.DataVencimento);
  return venc >= hoje && venc <= daqui7Dias;
});

const totalCR = crPendentes.reduce((s, p) => s + Number(p.Valor || 0), 0);
const totalCRInadimplente = crInadimplentes.reduce((s, p) => s + Number(p.Valor || 0), 0);
const totalCRRecebendo7d = crRecebendo7d.reduce((s, p) => s + Number(p.Valor || 0), 0);
const saldoLiquido = totalCR - totalCP;

// Fluxo semanal CR (entradas projetadas)
const fluxoCR = {};
for (const p of crPendentes) {
  const semana = getNumSemana(p.DataVencimento.split('T')[0]);
  if (!fluxoCR[semana]) fluxoCR[semana] = 0;
  fluxoCR[semana] += Number(p.Valor || 0);
}

// Projeção 4 semanas consolidada
const todasSemanas = new Set([...Object.keys(fluxoCP), ...Object.keys(fluxoCR)]);
const semanasOrdenadas = Array.from(todasSemanas).sort().slice(0, 4);
let saldoAcumulado = 0;
const projecao4Semanas = semanasOrdenadas.map(semana => {
  const entradas = fluxoCR[semana] || 0;
  const saidas = fluxoCP[semana] || 0;
  const saldoSemana = entradas - saidas;
  saldoAcumulado += saldoSemana;
  return { semana, entradas_previstas: Math.round(entradas*100)/100, saidas_previstas: Math.round(saidas*100)/100, saldo_semana: Math.round(saldoSemana*100)/100, saldo_acumulado: Math.round(saldoAcumulado*100)/100 };
});

const contasPagarJSON = {
  gerado_em: new Date().toISOString(),
  summary: { total_pendente: Math.round(totalCP*100)/100, total_vencido: Math.round(totalCPVencido*100)/100, total_vencendo_7d: Math.round(totalCPVencendo7d*100)/100 },
  vencidos: cpVencidos.sort((a,b) => Number(b.Valor||0) - Number(a.Valor||0)).slice(0,50).map(p => ({ id: p.Id, descricao: p.Descricao||p.NomeFornecedor||'N/A', valor: Number(p.Valor||0), data_vencimento: (p.DataVencimento||'').split('T')[0], dias_atraso: calcularDiasAtraso(p.DataVencimento||ctx.dataHoje) })),
  vencendo_7d: cpVencendo7d.sort((a,b) => Number(b.Valor||0) - Number(a.Valor||0)).map(p => ({ id: p.Id, descricao: p.Descricao||p.NomeFornecedor||'N/A', valor: Number(p.Valor||0), data_vencimento: (p.DataVencimento||'').split('T')[0] })),
  fluxo_semanal: Object.entries(fluxoCP).sort().map(([semana, total]) => ({ semana, total_saidas: Math.round(total*100)/100 }))
};

const contasReceberJSON = {
  gerado_em: new Date().toISOString(),
  summary: { total_pendente: Math.round(totalCR*100)/100, total_inadimplente: Math.round(totalCRInadimplente*100)/100, total_recebendo_7d: Math.round(totalCRRecebendo7d*100)/100, saldo_liquido: Math.round(saldoLiquido*100)/100 },
  inadimplentes: crInadimplentes.sort((a,b) => Number(b.Valor||0) - Number(a.Valor||0)).slice(0,50).map(p => ({ id: p.Id, cliente: p.Cliente||p.NomeCliente||'N/A', valor: Number(p.Valor||0), data_vencimento: (p.DataVencimento||'').split('T')[0], dias_atraso: calcularDiasAtraso(p.DataVencimento||ctx.dataHoje) })),
  recebendo_7d: crRecebendo7d.sort((a,b) => Number(b.Valor||0) - Number(a.Valor||0)).map(p => ({ id: p.Id, cliente: p.Cliente||p.NomeCliente||'N/A', valor: Number(p.Valor||0), data_vencimento: (p.DataVencimento||'').split('T')[0] })),
  fluxo_semanal: Object.entries(fluxoCR).sort().map(([semana, total]) => ({ semana, total_entradas: Math.round(total*100)/100 }))
};

const fluxoCaixaJSON = {
  gerado_em: new Date().toISOString(),
  saldo_liquido_atual: Math.round(saldoLiquido*100)/100,
  projecao_4_semanas: projecao4Semanas
};

return [{ json: { modulo: 'financeiro', dados: { contasPagar: contasPagarJSON, contasReceber: contasReceberJSON, fluxoCaixa: fluxoCaixaJSON } } }];

// ============================================================
// SALVAR ARQUIVOS JSON — Gravar em /data/erp/YYYY-MM-DD/
// ============================================================
const fs = require('fs');
const path = require('path');

const hoje = new Date().toISOString().split('T')[0];
const baseDir = `/data/erp/${hoje}`;

// Criar diretório se não existir
fs.mkdirSync(baseDir, { recursive: true });

// Coletar todos os dados dos módulos
let vendas = null, estoque = null, contasPagar = null, contasReceber = null, fluxoCaixa = null;

for (const item of $input.all()) {
  const { modulo, dados } = item.json;
  if (modulo === 'vendas') vendas = dados;
  if (modulo === 'estoque') estoque = dados;
  if (modulo === 'financeiro') {
    contasPagar = dados.contasPagar;
    contasReceber = dados.contasReceber;
    fluxoCaixa = dados.fluxoCaixa;
  }
}

// Salvar arquivos
const arquivos = [
  { nome: 'vendas.json', dados: vendas },
  { nome: 'estoque.json', dados: estoque },
  { nome: 'contas-pagar.json', dados: contasPagar },
  { nome: 'contas-receber.json', dados: contasReceber },
  { nome: 'fluxo-caixa.json', dados: fluxoCaixa }
];

const arquivosSalvos = [];
for (const arq of arquivos) {
  if (arq.dados) {
    const filePath = path.join(baseDir, arq.nome);
    fs.writeFileSync(filePath, JSON.stringify(arq.dados, null, 2), 'utf8');
    arquivosSalvos.push(filePath);
  }
}

// Criar/atualizar symlink 'latest' apontando para pasta mais recente
const latestPath = '/data/erp/latest';
try {
  if (fs.existsSync(latestPath)) fs.unlinkSync(latestPath);
  fs.symlinkSync(baseDir, latestPath);
} catch(e) {
  // symlink pode falhar em Windows/containers — ignorar
}

return [{
  json: {
    sucesso: true,
    data: hoje,
    arquivos_salvos: arquivosSalvos,
    resumo: {
      receita_total: vendas?.summary?.receita_total || 0,
      skus_criticos: estoque?.summary?.skus_criticos || 0,
      inadimplencia: contasReceber?.summary?.total_inadimplente || 0,
      saldo_liquido: contasReceber?.summary?.saldo_liquido || 0
    }
  }
}];
